using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class TypedPositiveSplitWordDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Endpoint-typed finite positive words with explicit corrections.",
        H("Endpoint-typed finite positive words with explicit corrections"),
        Blocks(
            Paragraph(Text("Word F H has exactly relabel, positive and comp constructors. A positive letter carries R,S together with actual finite graph relabelings from counted RS and SR to the endpoint presentations. Composition is indexed by its actual intermediate Presentation. Word.eval composes the resulting homeomorphisms, and Word.letters counts positive letters while relabels count zero.")),
            Paragraph(Text("Word.eval_time derives integer-time equivariance by induction over this syntax. Word.numbered_letter recovers the original counted elementaryHomeomorph in the two charts; Word.inverse_letter replaces its inverse by the opposite positive letter with a -1 correction. The outgoing/incoming words use the supplied edge numberings. outgoing_literal has no correction, outgoing_inverse_literal has -1, incoming_literal has -1, and incoming_inverse_literal has no correction. Those are derived equations for every original history, not input assumptions or new inverse/time/arbitrary-homeomorphism constructors.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-typedpositivesplitword-eval"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.eval"), H("eval"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Evaluate the endpoint-typed syntax by composing actual relabel homeomorphisms and positive elementary recodings. Every intermediate graph remains the specified presentation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-typedpositivesplitword-eval-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.eval_time"), H("eval_time"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Induction over relabel, positive and composition constructors proves signed-time equivariance of every evaluated word. It is derived from the leaf laws."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-word"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.Word"), H("Word"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A positive letter is bracketed by actual finite graph bijections. Composition is indexed by the literal intermediate finite presentation.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-letters"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.letters"), H("letters"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Count positive constructors and add under composition; graph relabels count zero. This measures the constructed word independently of its time correction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-identity"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.identity"), H("identity"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use the identity graph relabel as the zero-letter word at a presentation. No additional homeomorphism constructor is needed.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-numbered-letter"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.numbered_letter"), H("numbered_letter"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("In the two actual endpoint charts, evaluating one positive letter is the original counted elementary homeomorphism. The chart maps are retained explicitly.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-inverse-letter"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.inverse_letter"), H("inverse_letter"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Opposite POSITIVE letter, with the literal negative-unit correction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-out-old"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outOld"), H("outOld"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The outgoing supplier has finite edge bijections and both endpoint laws. Expose those as Relabel data; do not introduce another enumeration.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-out-next"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outNext"), H("outNext"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Package the outgoing supplier's numbered new-edge map and vertex numbering as the target graph relabel for a positive letter.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-out-old-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.out_old_number"), H("out_old_number"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Function-level equalities, including the existing supplier's exact parallel-edge numbering; no matrix-equality transport is hidden here.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-out-next-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.out_next_number"), H("out_next_number"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The target chart inverse equals the existing outgoing newPaths numbering on every history. This aligns the word chart with the supplied edge enumeration.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-outgoing"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outgoing"), H("outgoing"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Construct the outgoing traversal as one positive letter in its actual old and new charts. Its evaluation has no time correction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-outgoing-back"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outgoingBack"), H("outgoingBack"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use the opposite positive letter to traverse the outgoing split backwards. The later literal law retains its negative unit correction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-incoming"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.incoming"), H("incoming"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Construct the incoming traversal in the supplied incoming charts. Its literal lift requires a negative unit translation of this positive word.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-incoming-back"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.incomingBack"), H("incomingBack"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use the opposite incoming positive letter for reverse traversal. In this direction the literal forget law needs no time correction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-outgoing-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outgoing_literal"), H("outgoing_literal"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The outgoing word evaluates to the actual outgoing lift on every history. This is the unshifted forward case in tower accounting.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-outgoing-inverse-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.outgoing_inverse_literal"), H("outgoing_inverse_literal"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Outgoing forget is the reverse positive word followed by negative unit time. This is the outgoing contribution to backward correction counts.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-incoming-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.incoming_literal"), H("incoming_literal"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Incoming lift is the forward positive word followed by negative unit time. This is the incoming contribution to forward correction counts.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-typedpositivesplitword-incoming-inverse-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/TypedPositiveSplitWord.incoming_inverse_literal"), H("incoming_inverse_literal"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Incoming forget equals the reverse positive word without a correction. This completes the four literal split-direction laws.")))))));
}
